  let curr = [point[0], point[1], 1n];
  let result = null;
  let scalar = k;
  while (scalar > 0n) {
    if (scalar & 1n) result = jacAdd(result, curr);
    curr = jacDouble(curr);
    scalar >>= 1n;
  }
  return jacToAffine(result);
