  if (x >= P || x < 0n) return null;
  const ySq = mod(modPow(x, 3n) + 7n);
  let y = modPow(ySq, (P + 1n) / 4n);
  if (modPow(y, 2n) !== ySq) return null;
  if (y & 1n) y = P - y;
  return [x, y];
